/**
 * Pre-extracted authentic styles, fonts, borders, alignments, numFmts, colors,
 * column widths, row heights, merges, zoom, and print setups from source-exam.xlsx.
 * Covers all 15 worksheets so downloaded workbooks match the original Excel view.
 */

export interface CellStyle {
  fill?: { fgColor: { rgb: string } }
  font?: { bold?: boolean; italic?: boolean; underline?: boolean; color?: { rgb: string }; sz?: number; name?: string }
  border?: {
    top?: { style: string; color: { rgb: string } }
    bottom?: { style: string; color: { rgb: string } }
    left?: { style: string; color: { rgb: string } }
    right?: { style: string; color: { rgb: string } }
  }
  alignment?: { horizontal?: string; vertical?: string; wrapText?: boolean }
  numFmt?: string
}

export interface SheetLayoutMeta {
  cols?: Array<{ wch: number }>
  rows?: Array<{ hpt?: number; hpx?: number } | null>
  merges?: Array<{ s: { r: number; c: number }; e: { r: number; c: number } }>
  styles?: Record<string, CellStyle>
  zoomScale?: number
  defaultRowHeight?: number
  pageSetup?: { paperSize?: number; orientation?: 'portrait' | 'landscape' }
  margins?: { left: number; right: number; top: number; bottom: number; header: number; footer: number }
}

interface CompactSheetMeta extends Omit<SheetLayoutMeta, 'styles'> {
  styleRefs: Record<string, number>
}

