const expandedCache: Record<string, SheetLayoutMeta> = {}

export function getSheetMeta(sheetName: string): SheetLayoutMeta | null {
  const normKey = (sheetName || '').toLowerCase().replace(/[^a-z0-9]/g, '')
  if (!normKey) return null
  if (expandedCache[normKey]) return expandedCache[normKey]
  const raw = RAW_COMPACT_META[normKey]
  if (!raw) return null
  const styles: Record<string, CellStyle> = {}
  for (const [cellRef, pIdx] of Object.entries(raw.styleRefs)) {
    const st = STYLE_PALETTE[pIdx]
    if (st) styles[cellRef] = st
  }
  const expanded: SheetLayoutMeta = {
    cols: raw.cols,
    rows: raw.rows,
    merges: raw.merges,
    styles,
    zoomScale: raw.zoomScale,
    defaultRowHeight: raw.defaultRowHeight,
    pageSetup: raw.pageSetup,
    margins: raw.margins,
  }
  expandedCache[normKey] = expanded
  return expanded
}
